def dec(xi,c,off=None,thr=0.,K=(12,15)):
    x=torch.as_tensor(xi).float().clone(); c=torch.as_tensor(c).float(); fired=torch.zeros(len(x),dtype=torch.bool)
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.2.act",),count=False)
        if off is not None and K[0]<=k<K[1]:
            f=(a["blocks.2.act"]@w+b)>thr; fired|=f
            v=v+f[:,None].float()*torch.tensor(off)
        x=x-v/20
    return x.numpy(),fired.numpy()
